import type { ApiRoute, RouteBody, RouteParams, RouteResponse } from '../types/api';

export interface RetryOptions {
  maxRetries: number;
  backoff: 'linear' | 'exponential';
  baseDelayMs?: number;
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export async function retryWithBackoff<T>(request: () => Promise<T>, options: RetryOptions): Promise<T> {
  const baseDelayMs = options.baseDelayMs ?? 200;
  let attempt = 0;
  for (;;) {
    try {
      return await request();
    } catch (error) {
      attempt += 1;
      if (attempt > options.maxRetries) throw error;
      const delay = options.backoff === 'exponential' ? baseDelayMs * 2 ** (attempt - 1) : baseDelayMs * attempt;
      await sleep(delay);
    }
  }
}

/** Request options for a route: `params` and `body` are present only when the route takes them. */
export type ApiRequestOptions<R extends ApiRoute> = Omit<RequestInit, 'body' | 'method'> &
  ([RouteParams<R>] extends [never] ? { params?: never } : { params: RouteParams<R> }) &
  ([RouteBody<R>] extends [never] ? { body?: never } : { body: RouteBody<R> });

/** A route with no params and no body may be called without an options argument. */
type ApiRequestArgs<R extends ApiRoute> = [RouteParams<R>] extends [never]
  ? [RouteBody<R>] extends [never]
    ? [options?: ApiRequestOptions<R>]
    : [options: ApiRequestOptions<R>]
  : [options: ApiRequestOptions<R>];

function buildPath(pattern: string, params: Record<string, string> | undefined): string {
  return pattern.replace(/:([A-Za-z0-9_]+)/g, (_match, name: string) => {
    const value = params?.[name];
    if (value === undefined) throw new Error(`Missing path parameter ":${name}"`);
    return encodeURIComponent(value);
  });
}

export async function apiFetch<R extends ApiRoute>(
  route: R,
  ...[options]: ApiRequestArgs<R>
): Promise<RouteResponse<R>> {
  const [method, pattern] = route.split(' ') as [string, string];
  const { params, body, headers, ...init } = (options ?? {}) as ApiRequestOptions<ApiRoute> & {
    params?: Record<string, string>;
  };

  return retryWithBackoff(async () => {
    const response = await fetch(`/api${buildPath(pattern, params)}`, {
      ...init,
      method,
      headers: body === undefined ? headers : { 'content-type': 'application/json', ...headers },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
    return (await response.json()) as RouteResponse<R>;
  }, { maxRetries: 3, backoff: 'exponential' });
}

/**
 * Wire contract for the Express API in `server/routes.ts`, mounted under `/api`.
 *
 * These shapes are deliberately declared here rather than imported from the
 * server: they describe what crosses the network, not how the server stores it.
 */

export type Role = 'admin' | 'member' | 'viewer';

export interface Subscription {
  id: string;
  userId: string;
  plan: 'starter' | 'team' | 'enterprise';
  status: 'active' | 'past_due' | 'cancelled';
  renewsAt: string;
}

export interface Invoice {
  id: string;
  userId: string;
  amountCents: number;
  issuedAt: string;
  paid: boolean;
}

/** Body returned with any non-2xx response (401, 429, 404). */
export interface ApiError {
  error: string;
}

export interface LoginRequest {
  email: string;
  password: string;
}

export interface LoginResponse {
  token: string;
}

/** `GET /me` renames the JWT's `sub` claim to `id`. */
export interface MeResponse {
  id: string;
  role: Role;
}

export type SubscriptionsResponse = Subscription[];
export type InvoicesResponse = Invoice[];
export type CancelSubscriptionResponse = Subscription;

/**
 * Every route, keyed by `'<METHOD> <path pattern>'`. The key is the literal
 * pattern (`:id` and all), so callers pass path parameters separately and
 * `apiFetch` builds the URL. Routes omit `params`/`body` when they take none.
 */
export interface ApiRoutes {
  'POST /login': { body: LoginRequest; response: LoginResponse };
  'GET /me': { response: MeResponse };
  'GET /subscriptions': { response: SubscriptionsResponse };
  'GET /invoices': { response: InvoicesResponse };
  'POST /subscriptions/:id/cancel': { params: { id: string }; response: CancelSubscriptionResponse };
}

export type ApiRoute = keyof ApiRoutes & string;

export type RouteParams<R extends ApiRoute> = ApiRoutes[R] extends { params: infer P } ? P : never;
export type RouteBody<R extends ApiRoute> = ApiRoutes[R] extends { body: infer B } ? B : never;
export type RouteResponse<R extends ApiRoute> = ApiRoutes[R]['response'];
